import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# --------------------------------------------------------------------------
# Custom CUDA kernel for element‑wise addition (FP32)
# --------------------------------------------------------------------------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float()>, out.data_ptr<float()>, size);

    return out;
}
"""

# --------------------------------------------------------------------------
# Custom CUDA kernel for min reduction along a dimension
# --------------------------------------------------------------------------
min_reduction_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void min_reduction_kernel(const float* input, const int total_output_elements,
                                      float* output, int batch_size, int D1, int D2) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_output_elements) {
        // For a 3‑D tensor of shape (batch, D1, D2):
        //   dim == 0 : reduce over batch -> output size = D1*D2
        //   dim == 1 : each output corresponds to (b, d2_idx). total_output_elements = batch_size * D2.
        //   dim == 2 : each output corresponds to (b, d1_idx). total_output_elements = batch_size * D1.
        int b = idx / D2;          // only valid when dim==1
        int d2_idx = idx % D2;
        float min_val = 1e9f;
        for (int k = 0; k < D1; ++k) {
            float val = input[b * D1 * D2 + k * D2 + d2_idx];
            if (val < min_val) min_val = val;
        }
        output[idx] = min_val;
    }
}

torch::Tensor min_cuda(torch::Tensor input, int dim) {
    auto size = input.numel();
    auto out = torch::zeros_like(input);

    // Determine which dimension is being reduced.
    if (dim == 0) {
        int prod_other_dims = input.size(1) * input.size(2);
        total_output_elements = prod_other_dims;
        D1 = input.size(1);
        D2 = input.size(2);
    } else if (dim == 1) {
        int prod_other_dims = input.size(0) * input.size(2);
        total_output_elements = prod_other_dims;
        D1 = input.size(1);
        D2 = input.size(2);
    } else if (dim == 2) {
        int prod_other_dims = input.size(0) * input.size(1);
        total_output_elements = prod_other_dims;
        D1 = input.size(1);
        D2 = input.size(2);
    } else {
        #error "Unsupported dimension index: %d" % dim
    }

    const int block_size = 256;
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    min_reduction_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        total_output_elements,
        out.data_ptr<float>(),
        input.size(0), D1, D2
    );

    return out;
}
"""

# Load the custom operators.
elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

min_cuda = load_inline(
    name="min_cuda",
    cpp_sources=min_reduction_kernel_source,
    cuda_sources=min_reduction_kernel_source,
    functions=["min_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, dim: int = None) -> None:
        super().__init__()
        self.dim = dim if dim is not None else 1

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return min_cuda(x, dim=self.dim)
